\label{lem:single}
For nonempty $S$ and $i \in S$,
$R_0(S) - R_0(S \setminus \{i\}) = \theta_i\, g(A - a_i)\, [w_i - \phi\, e_i(S)]$.

\label{lem:envelope}
Assume~\eqref{eq:sd}. For $0 < \kappa \le \mu$,
$R^\star_\kappa - R^\star_\mu \le a_g \ln(\mu / \kappa)$.

\label{lem:fi}
Under Assumption~\ref{ass:sight} with rate $\varepsilon$, $k \ge 1$,
$W \ge 1$: (1) $P_{\mathrm{FI}}(1) = 1 - (1 - \varepsilon)^T$; (2)
$P_{\mathrm{FI}}(k) \le T \varepsilon \Pr(\mathrm{Bin}(W - 1, \varepsilon) \ge k - 1)
\le T \varepsilon \binom{W-1}{k-1} \varepsilon^{k-1}
\le T \varepsilon ((W - 1)\varepsilon)^{k-1} / (k-1)!$.
